def extract_patterns_from_demo(input_grid, output_grid):
    patterns = {}
    for r_in, row_in in enumerate(input_grid):
        for c_in, val in enumerate(row_in):
            # Output columns: 2*c_in and 2*c_in+1
            cols_start = 2 * c_in
            pattern = []
            for r_out in range(3):
                row_out = output_grid[r_out]
                col1 = row_out[cols_start]
                col2 = row_out[cols_start + 1]
                pattern.append([col1, col2])
            patterns[val] = pattern
    return patterns

